mapper.select:
/*selectMasterCmClSalesLogisticCostReg_Check*/

		SELECT
		    COUNT(*) AS CNT
		FROM 
		    BNTKEPTEXUP TM /* 매출물류비세금계산서 업로드 임시 테이블 */
		WHERE 1=1
		AND TM.BUYER = #{BUYER}
		AND TM.AGENT = #{AGENT}
		AND TM.AR_MONTH = #{AR_MONTH}
		AND TM.ISSUE_DATE = #{ISSUE_DATE}
		AND TM.SITE = 'KA'

/*selectMasterCmClSalesLogisticCostRegList*/
SELECT DECODE(TAX_BILL_NO, NULL, '미생성', '생성') AS STATUS , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'TX01' AND CODE = TM.KEP_IRS) AS KEP_IRS_NAME , TM.KEP_IRS AS KEP_IRS_NO , TM.BUYER , DECODE(IR.IRS_NO, NULL, CM.COM_NAME_LOC, IR.IRS_NAME) AS BUYER_NAME , TM.BUYER_IRS_NO , TM.AGENT , (SELECT COM_NAME_LOC FROM ICOMCMPY /* 회원사정보 */ WHERE COM_CODE = TM.AGENT) AS AGENT_NAME , TM.AGENT_IRS_NO , TM.DEPT_CODE AS KEP_DEPT , (SELECT TEXT2 FROM ICOMCOD1 /* 마스터코드 관리 */ WHERE TYPE = 'TX06' AND CODE = TM.DEPT_CODE) AS KEP_DEPT_NAME , TM.GR_AMT , TM.FEE_PERCENT , TM.LOGISTICS_FEE , TM.SUPP_PRICE , TM.TAX_PRICE , TM.AMT , TM.AR_CLOSE_MONTH , TM.AR_CLOSE_REVISION , TM.AR_MONTH , TM.ISSUE_DATE /*, '' AS LAST_DAY*/ FROM BNTKEPTEXUP TM /* 매출물류비세금계산서 업로드 임시 테이블 */ , ICOMCMPY CM /* 회원사정보 */ , KEPTIRSN IR /* 고객사 사업자정보 */ WHERE 1=1 AND TM.BUYER = CM.COM_CODE AND TM.SITE = IR.SITE(+) AND TM.BUYER_IRS_NO = IR.IRS_NO(+) AND TM.BUYER = IR.COM_CODE(+) AND TM.SITE = 'KA'
AND TM.BUYER = #{st_buyer_code}
AND TM.AR_MONTH = #{st_from_date} ORDER BY TM.BUYER , TM.AGENT , TM.ISSUE_DATE

mapper.update:
/*insertMasterCmClSalesLogisticCostReg*/

		INSERT INTO BNTKEPTEXUP /* 매출물류비세금계산서 업로드 임시 테이블 */
		(
		    BUYER
		  , AGENT
		  , AR_MONTH
		  , ISSUE_DATE

		  , KEP_IRS
		  , SITE
		  , BUYER_IRS_NO
		  , AGENT_IRS_NO
		  , DEPT_CODE

		  , GR_AMT
		  , FEE_PERCENT
		  , LOGISTICS_FEE
		  , SUPP_PRICE
		  , TAX_PRICE
		  , AMT

		  , AR_CLOSE_MONTH
		  , AR_CLOSE_REVISION
		  , ADD_USER_ID
		  , CREATE_DATETIME
		)
		VALUES
		(
		    #{BUYER}
		  , #{AGENT}
		  , #{AR_MONTH}
		  , #{ISSUE_DATE}

		  , #{KEP_IRS_NO}
		  , 'KA'
		  , #{BUYER_IRS_NO}
		  , #{AGENT_IRS_NO}
		  , #{KEP_DEPT}

		  , #{GR_AMT}
		  , #{FEE_PERCENT}
		  , #{LOGISTICS_FEE}
		  , #{SUPP_PRICE}
		  , #{TAX_PRICE}
		  , #{AMT}

		  , ''
		  , ''
		  , #{st_user_id}
		  , SYSDATE
		)

/*updateMasterCmClSalesLogisticCostReg*/

		UPDATE BNTKEPTEXUP /* 매출물류비세금계산서 업로드 임시 테이블 */
		SET TAX_BILL_NO       = #{order_no}
		  , AR_CLOSE_MONTH    = #{AR_MONTH}
		  , AR_CLOSE_REVISION = #{st_close_revision}
		WHERE 1=1
		AND BUYER      = #{BUYER} 
		AND AGENT      = #{AGENT}
		AND AR_MONTH   = #{AR_MONTH}
		AND ISSUE_DATE = #{ISSUE_DATE} 
		AND TAX_BILL_NO IS NULL


DELETE 
    BNTKEPTEXUP /* 매출물류비세금계산서 업로드 임시 테이블 */ 
WHERE 1=1 
AND BUYER = #{BUYER} 
AND AGENT = #{AGENT} 
AND AR_MONTH = #{AR_MONTH}
AND ISSUE_DATE = #{ISSUE_DATE}
AND TAX_BILL_NO IS NULL
